data.query:
mutation AttachmentCreate($input: AttachmentCreateInput!) {
                    attachmentCreate(input: $input) {
                        success
                        attachment {
                            id
                            title
                            subtitle
                            url
                            metadata
                            sourceType
                            createdAt
                            updatedAt
                            issue {
                                id
                            }
                        }
                    }
                }
